//! The interface Swift sees, generated by UniFFI (plan step 3). A thin wrapper around
//! [`crate::EspansoEngine`]: Swift objects are shared, so the engine sits behind a mutex,
//! and the script runner is a Swift callback.

use std::collections::HashMap;
use std::path::Path;
use std::sync::{Arc, Mutex};

use crate::engine::{Expansion, SnippetSummary};
use crate::script::ScriptOutput;

#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum EspansoError {
    /// The Espanso folder couldn't be loaded.
    #[error("{message}")]
    Load { message: String },
    /// The script couldn't run at all (missing file, time limit).
    #[error("{message}")]
    Script { message: String },
}

impl From<uniffi::UnexpectedUniFFICallbackError> for EspansoError {
    fn from(error: uniffi::UnexpectedUniFFICallbackError) -> Self {
        Self::Script {
            message: error.reason,
        }
    }
}

/// Runs a script file; implemented in Swift with JavaScriptCore.
#[uniffi::export(callback_interface)]
pub trait ScriptRunner: Send + Sync {
    /// `argv` is `[runtime, script path, ...rest]`; `env` holds `CONFIG` and the
    /// `ESPANSO_<NAME>` variables. Throws only when the script can't run at all.
    fn run(
        &self,
        script_path: String,
        argv: Vec<String>,
        env: HashMap<String, String>,
    ) -> Result<ScriptOutput, EspansoError>;
}

struct ForeignRunner(Box<dyn ScriptRunner>);

impl crate::script::ScriptRunner for ForeignRunner {
    fn run(
        &self,
        script_path: &str,
        argv: &[String],
        env: &HashMap<String, String>,
    ) -> anyhow::Result<ScriptOutput> {
        Ok(self
            .0
            .run(script_path.to_string(), argv.to_vec(), env.clone())?)
    }
}

/// Espanso snippet expansion for one keyboard. See [`crate::EspansoEngine`] for the
/// order of calls.
#[derive(uniffi::Object)]
pub struct EspansoEngine {
    inner: Mutex<crate::EspansoEngine>,
}

#[uniffi::export]
impl EspansoEngine {
    /// Loads the Espanso folder at `config_folder`.
    #[uniffi::constructor]
    pub fn new(
        config_folder: String,
        script_runner: Box<dyn ScriptRunner>,
    ) -> Result<Arc<Self>, EspansoError> {
        let engine = crate::EspansoEngine::new(
            Path::new(&config_folder),
            Arc::new(ForeignRunner(script_runner)),
        )
        .map_err(|e| EspansoError::Load {
            message: format!("{e:#}"),
        })?;
        Ok(Arc::new(Self {
            inner: Mutex::new(engine),
        }))
    }

    /// One key press, after the keyboard inserted it. May run a script, so call it off
    /// the main thread.
    pub fn type_text(&self, text: String) -> Option<Expansion> {
        self.engine().type_text(&text)
    }

    /// Backspace, before the keyboard deletes. A returned expansion replaces the delete.
    pub fn backspace(&self) -> Option<Expansion> {
        self.engine().backspace()
    }

    /// The cursor moved, the field changed or the keyboard reappeared.
    pub fn reset(&self) {
        self.engine().reset()
    }

    pub fn search(&self, query: String) -> Vec<SnippetSummary> {
        self.engine().search(&query)
    }

    pub fn warnings(&self) -> Vec<String> {
        self.engine().warnings().to_vec()
    }

    /// Why the last completed trigger didn't expand, if it didn't.
    pub fn last_error(&self) -> Option<String> {
        self.engine().last_error().map(str::to_string)
    }
}

impl EspansoEngine {
    fn engine(&self) -> std::sync::MutexGuard<'_, crate::EspansoEngine> {
        // A panic aborts (panic = "abort" in release), so a poisoned lock only
        // happens in debug builds; keep going with the state as it is.
        self.inner.lock().unwrap_or_else(|e| e.into_inner())
    }
}
